			continue
		}
		cmd := buildCommand(method, pathStr, op, pathItem.Parameters)
		groupName := cmd.GroupName

		if _, ok := groupMap[groupName]; !ok {
			groupMap[groupName] = &model.CommandGroup{
				Name: groupName,
			}
